const listCharges = `-- name: ListCharges :many
SELECT id, tenant_id, invoice_id, customer_id, provider_account_id, provider, attempt, provider_charge_id, status, amount, currency, amount_paid, fee_amount, amount_refunded, amount_charged_back, checkout_url, due_date, paid_at, failure_reason, provider_status, provider_status_at, created_at, updated_at, version, amount_refund_pending FROM charges
 WHERE tenant_id = $1
   AND ($2::text IS NULL OR status = $2)
   AND ($3::uuid IS NULL OR invoice_id = $3)
   AND ($4::timestamptz IS NULL OR (created_at, id) < ($4::timestamptz, $5::uuid))
 ORDER BY created_at DESC, id DESC
 LIMIT $6
`

type ListChargesParams struct {
	TenantID  uuid.UUID
	Status    *string
	InvoiceID *uuid.UUID
	CursorTs  *time.Time
	CursorID  *uuid.UUID
	RowLimit  int32
}

func (q *Queries) ListCharges(ctx context.Context, arg ListChargesParams) ([]Charge, error) {
	rows, err := q.db.Query(ctx, listCharges,
		arg.TenantID,
		arg.Status,
		arg.InvoiceID,
		arg.CursorTs,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Charge
	for rows.Next() {
		var i Charge
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.InvoiceID,
			&i.CustomerID,
			&i.ProviderAccountID,
			&i.Provider,
			&i.Attempt,
			&i.ProviderChargeID,
			&i.Status,
			&i.Amount,
			&i.Currency,
			&i.AmountPaid,
			&i.FeeAmount,
			&i.AmountRefunded,
			&i.AmountChargedBack,
			&i.CheckoutUrl,
			&i.DueDate,
			&i.PaidAt,
			&i.FailureReason,
			&i.ProviderStatus,
			&i.ProviderStatusAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
			&i.AmountRefundPending,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

